mapper.select:
SELECT speed_kmh FROM vehicle_telemetry
WHERE vehicle_id = #{vehicleId} AND driver_id = #{driverId}
  AND sampled_at BETWEEN #{earliest} AND #{capturedAt}
ORDER BY sampled_at DESC LIMIT 1

SELECT vehicle_id, driver_id, sampled_at, latitude, longitude, speed_kmh, received_at, coordinate_system
FROM vehicle_telemetry WHERE vehicle_id = #{vehicleId} AND ingest_id <= #{snapshotId}
  AND sampled_at >= #{start} AND sampled_at < #{end}
ORDER BY sampled_at, driver_id LIMIT #{limit}

SELECT vehicle_id, driver_id, sampled_at, latitude, longitude, speed_kmh, received_at, coordinate_system
FROM vehicle_telemetry WHERE vehicle_id = #{vehicleId} AND driver_id = #{driverId}
ORDER BY sampled_at DESC LIMIT 1

mapper.sql:
WITH current_binding AS ( SELECT v.id AS vehicle_id, v.fleet_id, CASE WHEN COUNT(u.id)=1 THEN MIN(u.id) END AS driver_id, COUNT(u.id) AS driver_count FROM vehicle v LEFT JOIN sys_user u ON u.vehicle_id=v.id AND u.fleet_id=v.fleet_id AND u.role='DRIVER' AND u.enabled=1 WHERE v.id IN
#{vehicleId}
GROUP BY v.id, v.fleet_id )

mapper.select:
SELECT id, departed_at FROM transport_task WHERE id=#{taskId} AND vehicle_id=#{vehicleId}
    AND driver_id=#{driverId} AND fleet_id=#{fleetId} AND status='RUNNING' AND departed_at IS NOT NULL
FOR UPDATE
